import{_ as t,D as o,c as n,I as i,a4 as a,j as s,o as l}from"./chunks/framework.CRCV4hx_.js";const k=JSON.parse('{"title":"Affiliates","description":"","frontmatter":{},"headers":[],"relativePath":"affiliates.md","filePath":"affiliates.md"}'),r={name:"affiliates.md"},f=a('<h1 id="affiliates" tabindex="-1">Affiliates <a class="header-anchor" href="#affiliates" aria-label="Permalink to &quot;Affiliates&quot;">​</a></h1><p>Resrv offers a basic affiliate system that allows you to track any reservations made through an affiliate link. In this page, we&#39;ll go over how to set up and use the affiliate system.</p><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h2><p>To use the affiliate system, you need to enable it in the addon&#39;s <a href="./configuration#engine">configuration</a> page. Once enabled, you can find the Affiliates link in the Control Panel.</p><p>When adding an affiliate, you will be presented with the following options:</p>',5),h=a('<ul><li><strong>Name</strong>: The name of the affiliate, for your own reference.</li><li><strong>Code</strong>: The affiliate code that will be part of the affiliate link.</li><li><strong>Email</strong>: The email address of the affiliate.</li><li><strong>Cookie duration in days</strong>: How long the affiliate cookie should remain valid. After this time, the cookie will expire, and the affiliate will no longer be credited for any reservation by that user.</li><li><strong>Fee</strong>: The fee as a percentage of the reservation that the affiliate earns. This is only for your reference; the affiliate does not see this.</li><li><strong>Allow skipping payment</strong>: If enabled, the affiliate will be able to skip the payment step in the checkout process.</li><li><strong>Send reservation email</strong>: If enabled, the affiliate will receive a confirmation email whenever a reservation is made through their link.</li><li><strong>Published</strong>: If disabled, the affiliate will be temporarily unpublished.</li></ul><h2 id="getting-the-affiliate-link" tabindex="-1">Getting the affiliate link <a class="header-anchor" href="#getting-the-affiliate-link" aria-label="Permalink to &quot;Getting the affiliate link&quot;">​</a></h2><p>Once you&#39;ve added an affiliate, you can get the affiliate link by clicking on the action menu in the affiliate list and selecting &quot;Copy affiliate link,&quot; or you can manually add <code>?afid=CODE</code> at the end of any URL on your website (where <code>CODE</code> is the affiliate code you set in the affiliate settings).</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When a user visits your site using the affiliate link, a cookie is set on their browser. This cookie contains the affiliate code and remains active for the number of days you specified in the affiliate settings. If a reservation is made through this affiliate link, the affiliate will be credited for that reservation.</p><p>The cookie gets overwritten each time a new visit is made using a different affiliate link, so the most recent visit always sets the active cookie.</p><p>However, this approach has some limitations. For instance, if a user blocks cookies by default, the reservation will not be credited to the affiliate.</p><h2 id="skipping-payment" tabindex="-1">Skipping payment <a class="header-anchor" href="#skipping-payment" aria-label="Permalink to &quot;Skipping payment&quot;">​</a></h2><p>As previously mentioned, if you enable the <strong>Allow skipping payment</strong> option, the affiliate will be able to bypass the payment step during the checkout process. This feature is useful if you want an affiliate to book a reservation on behalf of a client without immediate payment, for example, if an agency or concierge is booking for a client who will pay later. Be cautious when using this feature, as sharing the affiliate code may allow other users to bypass payment unintentionally.</p><p>When skipping payment is allowed, a new button labeled <strong>Complete reservation and pay later</strong> will appear in the checkout process after entering the client&#39;s details.</p><h2 id="how-to-credit-affiliates" tabindex="-1">How to credit affiliates <a class="header-anchor" href="#how-to-credit-affiliates" aria-label="Permalink to &quot;How to credit affiliates&quot;">​</a></h2><p>In the <a href="./reservations#reservation-details">reservation details</a> page, you can see the affiliate that was credited for the reservation:</p>',12),d=s("p",null,"The fees displayed here are for your convienience only, the affiliate does not see this information.",-1);function c(p,u,g,m,y,w){const e=o("Image");return l(),n("div",null,[f,i(e,{src:"./img/resrv-affiliates-add.webp",alt:"Adding a new affiliate."}),h,i(e,{src:"./img/resrv-reservation-affiliate-credit.webp",alt:"What appears in the reservations details page when an affiliate is credited."}),d])}const _=t(r,[["render",c]]);export{k as __pageData,_ as default};
